def S(n):
    return sum(int(d) for d in str(n))

def check(n):
    for k in range(n, n + 38):
        if S(k) % 11 == 0:
            return False
    return True

# Let's search for the smallest n up to some limit
limit = 100000
found_n = -1
for n in range(1, limit):
    if check(n):
        found_n = n
        break

print(f"Smallest n up to {limit}: {found_n}")

